// The templates that `minispec new` writes for each tier (spec `minispec`, "Size tiers").
// Each template holds the headings and one example, and the skills tell Claude to replace the example.
// Each check in `tasks.md` is a command in a code span, so a reviewer can run it.

import {
  DESIGN_TEMPLATE,
  PROPOSAL_TEMPLATE,
  SPEC_TEMPLATE,
  TASKS_TEMPLATE,
} from "../prompts.ts";
import { hasDesign, type Tier } from "./tiers.ts";

/** The text of `proposal.md` for the change `name`. */
export const proposalTemplate = (name: string, tier: Tier): string =>
  `${PROPOSAL_TEMPLATE({ name, tier })}
`;

/** The text of `tasks.md`. */
export const tasksTemplate = (): string => `${TASKS_TEMPLATE}
`;

/** The text of `design.md`. */
export const designTemplate = (name: string): string =>
  `${DESIGN_TEMPLATE({ name })}
`;

/** The text of the delta spec of the capability `capability`. */
export const specTemplate = (capability: string): string =>
  `${SPEC_TEMPLATE({ capability })}
`;

/** The files of a new change: the path inside the change folder and the text, for the tier. */
export const filesOf = (
  name: string,
  tier: Tier,
  capability: string,
): [string, string][] => [
  ["proposal.md", proposalTemplate(name, tier)],
  ["tasks.md", tasksTemplate()],
  ...(hasDesign(tier)
    ? ([
        ["design.md", designTemplate(name)],
        [`specs/${capability}/spec.md`, specTemplate(capability)],
      ] as [string, string][])
    : []),
];
